#!/usr/bin/env bash
# =============================================================================
# Bahn Project Manager - Stage 4b: PDF export, Aenderungshistorie, E2E suite
#
#   git checkout -b stage4pdf
#   git fetch origin main && git checkout origin/main -- stage4bpdf.sh
#   bash stage4bpdf.sh
#
# Adds one dependency (@react-pdf/renderer), so pnpm install is REQUIRED.
# =============================================================================
set -euo pipefail
EXPECTED_SHA="c249850cad306c01400031c7f15bd6095581cff22b90e3a2c7afcc94bab6b2d6"

[ -f package.json ] && [ -d client/src ] || { echo "!! run from the repository root" >&2; exit 1; }
if [ -d client/src/pdf ]; then echo "!! already applied - client/src/pdf exists" >&2; exit 0; fi
if [ ! -f shared/contacts.ts ]; then
  echo "!! prerequisite missing - land stage 4a first (shared/contacts.ts)" >&2; exit 1; fi

DIRTY="$(git status --porcelain | grep -v "stage4bpdf\.sh$" || true)"
[ -z "$DIRTY" ] || { echo "!! working tree is dirty" >&2; echo "$DIRTY" >&2; exit 1; }

TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
echo "==> extracting payload"
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d | gzip -d > "$TMP/p.patch"
ACTUAL="$(sha256sum "$TMP/p.patch" | cut -d' ' -f1)"
[ "$ACTUAL" = "$EXPECTED_SHA" ] || { echo "!! checksum mismatch" >&2; echo "   expected $EXPECTED_SHA" >&2; echo "   actual   $ACTUAL" >&2; exit 1; }
echo "    checksum ok"
echo "==> applying"; git apply --whitespace=nowarn "$TMP/p.patch"; echo "    ok"

cat <<'EOF'
---------------------------------------------------------------------------
Applied. pnpm install is REQUIRED this time - @react-pdf/renderer is new.

  pnpm install
  pnpm check && pnpm lint && pnpm test:cov && pnpm verify:data \
    && NODE_ENV=production pnpm build:client
  pnpm e2e

Expected:
  0 type errors
  85 lint warnings
  124 passed / 6 skipped
  contacts: 51 Adressen | 13/14 Gewerke erreichbar | ohne Adresse: LST
  entry chunk still 429 kB; react-pdf is a separate 1.29 MB lazy chunk
  e2e: 14 passed, 0 failed

Then land it:
  git add -A && git commit -m "stage 4b: PDF export, Aenderungshistorie, e2e"
  git checkout main && git pull --ff-only
  git merge --no-ff stage4pdf -m "stage 4b: PDF export, Aenderungshistorie, e2e"
  git rm -f stage4bpdf.sh && git commit -m "remove applied bootstrap artifact"
  git push && git branch -d stage4pdf
---------------------------------------------------------------------------
EOF
exit 0

